// Bundles src/editor/sanitize-entry.ts (DOMPurify and the hooks that route the rich text editor's HTML through it) into a
// string the editor's page runs: src/generated/editor-sanitize.ts. Run again after updating dompurify (`yarn build:editor`);
// scripts/sanitize.test.mjs fails while the generated file is out of date.
import * as esbuild from "esbuild";
import { readFileSync, writeFileSync } from "fs";
import { pathToFileURL } from "url";

export const OUTPUT = "src/generated/editor-sanitize.ts";

/** The bundle and the DOMPurify version in it. */
export async function bundleSanitizer() {
  const result = await esbuild.build({
    entryPoints: ["src/editor/sanitize-entry.ts"],
    bundle: true,
    format: "iife",
    write: false,
    minify: true,
    target: "es2020",
    legalComments: "inline",
  });
  const js = result.outputFiles[0].text;
  // On web the script is put into the editor's HTML with `html.replace("</body>", "<script>" + js + ...)`: nothing in it
  // may end or reopen a script element, nor read as a replacement pattern ($&, $1...).
  const unsafe = [/<\/script/i, /<script/i, /\$[&`'$<\d]/].find((pattern) => pattern.test(js));
  if (unsafe) throw new Error(`the bundle contains ${unsafe}: it can't be put into the editor's HTML as it is`);
  const version = JSON.parse(readFileSync("node_modules/dompurify/package.json", "utf8")).version;
  return { js, version };
}

/** The generated module's text. */
export const moduleText = ({ js, version }) =>
  `// Auto-generated by scripts/build-sanitize.mjs — DO NOT EDIT\n` +
  `export const DOMPURIFY_VERSION = ${JSON.stringify(version)};\n` +
  `export const EDITOR_SANITIZE_JS = ${JSON.stringify(js)};\n`;

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const bundle = await bundleSanitizer();
  writeFileSync(OUTPUT, moduleText(bundle));
  console.log(`${OUTPUT}: DOMPurify ${bundle.version}, ${bundle.js.length} characters`);
}
